  "<!doctype html><html lang=\"hr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><title>Prinosi na stablecoine</title><meta name=\"description\" content=\"Vrste DeFi usluga za stablecoine i bazeni s najvišim prinosom.\"><meta property=\"og:title\" content=\"Prinosi na stablecoine\"><meta property=\"og:description\" content=\"Vrste DeFi usluga za stablecoine i bazeni s najvišim prinosom.\"><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Ccircle cx='16' cy='16' r='15' fill='%230f6e63'/%3E%3Ctext x='16' y='22' font-family='Arial' font-weight='700' font-size='18' text-anchor='middle' fill='white'%3E$%3C/text%3E%3C/svg%3E\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap\"></head><body><aside class=\"sc-side\" aria-label=\"Izbornik\"><a class=\"sc-logo\" href=\"/\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" s",
