  "+ \"</b><span>\" + esc(l) + \"</span></div>\"; }\n\n  // Povijest se računa unatrag od trenutnog stanja, pa vrijedi i kad nije dohvaćena cijela povijest.\n  function series(r) {\n    var now = Date.now() / 1000, total = 0;\n    r.holdings.forEach(function (h) { if (!EUR[h.sym]) total += h.bal; });\n    var ev = r.events.filter(function (e) { return !EUR[e.sym]; }).sort(function (a, b) { return b.ts - a.ts; });\n    var pts = [{ t: now, v: total }], v = total;\n    ev.forEach(function (e) { pts.push({ t: e.ts, v: v, e: e }); v -= e.d; pts.push({ t: e.ts, v: Math.max(0, v) }); });\n    pts.push({ t: ev.length ? ev[ev.length - 1].ts - 86400 * 3 : now - 86400 * 30, v: Math.max(0, v) });\n    return pts.reverse();\n  }\n  function nice(max) {\n    if (max <= 0) return { max: 1, step: 0.25 };\n    var raw = max / 4, mag = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / mag;\n    var step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * mag;\n    return { max: Math.ceil(max / step) * step, step: step };\n  }\n  function axisMoney(v) { return v >= 1e9 ? nf0.format(v / 1e9) + \" mlrd.\" : v >= 1e6 ? nf0.format(v / 1e6) + \" mil.\" : v >= 1e3 ? nf0.format(v / 1e3) + \" tis.\" : nf0.format(v); }\n  function drawChart(r) {\n    var pts = series(r), W = Math.max(300, Math.round($(\"chart\").clientWidth || 800)), H = W < 500 ? 200 : 240, L = 56, R = 14, T = 12, B = 28;\n    var t0 = pts[0].t, t1 = pts[pts.length - 1].t; if (t1 <= t0) t1 = t0 + 1;\n    var vmax = Math.max.apply(null, pts.map(function (p",
  ") { return p.v; })), n = nice(vmax * 1.05);\n    var x = function (t) { return L + (t - t0) / (t1 - t0) * (W - L - R); };\n    var y = function (v) { return T + (1 - v / n.max) * (H - T - B); };\n    var s = '<svg class=\"hist\" viewBox=\"0 0 ' + W + \" \" + H + '\" role=\"img\" aria-label=\"Ukupno stanje stablecoina kroz vrijeme\">';\n    for (var g = 0; g <= n.max + 1e-9; g += n.step) s += '<line class=\"grid\" x1=\"' + L + '\" x2=\"' + (W - R) + '\" y1=\"' + y(g) + '\" y2=\"' + y(g) + '\"/><text x=\"' + (L - 8) + '\" y=\"' + (y(g) + 4) + '\" text-anchor=\"end\">' + axisMoney(g) + \"</text>\";\n    var span = t1 - t0, ticks = W < 500 ? 2 : 5;\n    for (var i = 0; i <= ticks; i++) { var tt = t0 + span * i / ticks; s += '<text x=\"' + x(tt) + '\" y=\"' + (H - 8) + '\" text-anchor=\"' + (i === 0 ? \"start\" : i === ticks ? \"end\" : \"middle\") + '\">' + df.format(new Date(tt * 1000)) + \"</text>\"; }\n    var d = pts.map(function (p, k) { return (k ? \"L\" : \"M\") + x(p.t).toFixed(1) + \" \" + y(p.v).toFixed(1); }).join(\" \");\n    s += '<path class=\"area\" d=\"' + d + \" L\" + x(t1) + \" \" + y(0) + \" L\" + x(t0) + \" \" + y(0) + 'Z\"/><path class=\"line\" d=\"' + d + '\"/>';\n    s += '<line class=\"cross\" id=\"cross\" y1=\"' + T + '\" y2=\"' + (H - B) + '\" x1=\"-10\" x2=\"-10\"/><circle class=\"dot\" id=\"cdot\" r=\"4\" cx=\"-10\" cy=\"-10\"/>';\n    s += '<circle class=\"dot\" r=\"4\" cx=\"' + x(t1) + '\" cy=\"' + y(pts[pts.length - 1].v) + '\"/>';\n    s += '<rect id=\"hit\" x=\"' + L + '\" y=\"0\" width=\"' + (W - L - R) + '\" height=\"' + H + '\" fill=\"transparent\"/></svg>';\n  ",
  "  $(\"chart\").innerHTML = s;\n    $(\"readout\").textContent = \"Danas: \" + money(pts[pts.length - 1].v);\n    var svg = $(\"chart\").firstChild;\n    function at(evt) {\n      var rect = svg.getBoundingClientRect(), px = (evt.clientX - rect.left) / rect.width * W;\n      var t = t0 + (px - L) / (W - L - R) * (t1 - t0), v = pts[0].v;\n      for (var k = 0; k < pts.length; k++) { if (pts[k].t <= t) v = pts[k].v; else break; }\n      var cx = Math.max(L, Math.min(W - R, px));\n      $(\"cross\").setAttribute(\"x1\", cx); $(\"cross\").setAttribute(\"x2\", cx);\n      $(\"cdot\").setAttribute(\"cx\", cx); $(\"cdot\").setAttribute(\"cy\", y(v));\n      $(\"readout\").textContent = df.format(new Date(Math.min(t1, Math.max(t0, t)) * 1000)) + \": \" + money(v);\n    }\n    svg.addEventListener(\"pointermove\", at);\n    svg.addEventListener(\"pointerleave\", function () { $(\"cross\").setAttribute(\"x1\", -10); $(\"cross\").setAttribute(\"x2\", -10); $(\"cdot\").setAttribute(\"cx\", -10); $(\"readout\").textContent = \"Danas: \" + money(pts[pts.length - 1].v); });\n  }\n\n  // ---------- Pokretanje ----------\n  function statusFn() {\n    var box = $(\"progress\"); box.innerHTML = \"\"; box.hidden = false;\n    var rows = {};\n    return function (name, text, kind) {\n      if (!rows[name]) { rows[name] = document.createElement(\"div\"); rows[name].className = \"row\"; box.appendChild(rows[name]); }\n      rows[name].innerHTML = \"<b>\" + esc(name) + '</b><span class=\"st ' + (kind || \"\") + '\">' + esc(text) + \"</span>\";\n    };\n  }\n  function kindOf(a) {\n    if ",
  "(/^0x[0-9a-fA-F]{40}$/.test(a)) return \"evm\";\n    if (/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(a)) return \"sol\";\n    return null;\n  }\n  var busy = false;\n  $(\"form\").addEventListener(\"submit\", function (ev) {\n    ev.preventDefault();\n    var a = $(\"addr\").value.trim(), k = kindOf(a);\n    if (!k) { $(\"hint\").textContent = \"To nije ispravna adresa. EVM adresa počinje s 0x i ima 42 znaka, a Solana adresa ima 32 do 44 znaka bez 0, O, I i l.\"; return; }\n    if (busy) return;\n    busy = true; $(\"go\").disabled = true;\n    try { localStorage.setItem(\"wc-addr\", a); } catch (e) {}\n    var status = statusFn();\n    (k === \"evm\" ? checkEvm(a, status) : checkSolana(a, status)).then(function (r) { render(a, r); }).catch(function (e) { status(\"Greška\", errText(e, k === \"evm\" ? ES : SOL), \"err\"); })\n      .then(function () { busy = false; $(\"go\").disabled = false; });\n  });\n  try { var saved = localStorage.getItem(\"wc-addr\"); if (saved) $(\"addr\").value = saved; } catch (e) {}\n\n})();\n</script>\n<footer class=\"sc-site-foot\">Podaci: DefiLlama, CoinMarketCap, Blockscout i Helius. Stranica ne daje financijske savjete.</footer></div><style>\n:root { --side-w: 228px; --side-bg: #17271f; --side-ink: #e8efe9; --side-muted: #93a79b; --side-act: #263b31; --lime: #c6f16b; --lime-ink: #13201a; }\nhtml:root:not(#v2) {\n  --bg: #f4f5f1; --surface: #ffffff; --ink: #121c17; --muted: #5a6d62; --line: #e2e6de;\n  --accent: #2d5b45; --accent-soft: #edf5df; --hero-a: #ffffff; --hero-b: #ffffff; --hero-ink: #121c17;\n  --f-",
