  "function fig(v, l) { return '<div class=\"fig\"><b>' + v + \"</b><span>\" + esc(l) + \"</span></div>\"; }\n\n  // Povijest se računa unatrag od trenutnog stanja, pa vrijedi i kad nije dohvaćena cijela povijest.\n  function series(r) {\n    var now = Date.now() / 1000, total = 0;\n    r.holdings.forEach(function (h) { if (!EUR[h.sym]) total += h.bal; });\n    var ev = r.events.filter(function (e) { return !EUR[e.sym]; }).sort(function (a, b) { return b.ts - a.ts; });\n    var pts = [{ t: now, v: total }], v = total;\n    ev.forEach(function (e) { pts.push({ t: e.ts, v: v, e: e }); v -= e.d; pts.push({ t: e.ts, v: Math.max(0, v) }); });\n    pts.push({ t: ev.length ? ev[ev.length - 1].ts - 86400 * 3 : now - 86400 * 30, v: Math.max(0, v) });\n    return pts.reverse();\n  }\n  function nice(max) {\n    if (max <= 0) return { max: 1, step: 0.25 };\n    var raw = max / 4, mag = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / mag;\n    var step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * mag;\n    return { max: Math.ceil(max / step) * step, step: step };\n  }\n  function axisMoney(v) { return v >= 1e9 ? nf0.format(v / 1e9) + \" bn\" : v >= 1e6 ? nf0.format(v / 1e6) + \" M\" : v >= 1e3 ? nf0.format(v / 1e3) + \" k\" : nf0.format(v); }\n  function drawChart(r) {\n    var pts = series(r), W = Math.max(300, Math.round($(\"chart\").clientWidth || 800)), H = W < 500 ? 200 : 240, L = 56, R = 14, T = 12, B = 28;\n    var t0 = pts[0].t, t1 = pts[pts.length - 1].t; if (t1 <= t0) t1 = t0 + 1;\n    var v",
