  "\n    };\n  }\n  function kindOf(a) {\n    if (/^0x[0-9a-fA-F]{40}$/.test(a)) return \"evm\";\n    if (/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(a)) return \"sol\";\n    return null;\n  }\n  var busy = false;\n  $(\"form\").addEventListener(\"submit\", function (ev) {\n    ev.preventDefault();\n    var a = $(\"addr\").value.trim(), k = kindOf(a);\n    if (!k) { $(\"hint\").textContent = \"That is not a valid address. An EVM address starts with 0x and has 42 characters; a Solana address has 32 to 44 characters without 0, O, I and l.\"; return; }\n    if (busy) return;\n    busy = true; $(\"go\").disabled = true;\n    try { localStorage.setItem(\"wc-addr\", a); } catch (e) {}\n    var status = statusFn();\n    (k === \"evm\" ? checkEvm(a, status) : checkSolana(a, status)).then(function (r) { render(a, r); }).catch(function (e) { status(\"Error\", errText(e, k === \"evm\" ? ES : SOL), \"err\"); })\n      .then(function () { busy = false; $(\"go\").disabled = false; });\n  });\n  try { var saved = localStorage.getItem(\"wc-addr\"); if (saved) $(\"addr\").value = saved; } catch (e) {}\n\n})();\n</script>\n<footer class=\"sc-site-foot\">Data: DefiLlama, CoinMarketCap, Blockscout and Helius. This site does not give financial advice.</footer></div><style>\n:root { --side-w: 228px; --side-bg: #17271f; --side-ink: #e8efe9; --side-muted: #93a79b; --side-act: #263b31; --lime: #c6f16b; --lime-ink: #13201a; }\nhtml:root:not(#v2) {\n  --bg: #f4f5f1; --surface: #ffffff; --ink: #121c17; --muted: #5a6d62; --line: #e2e6de;\n  --accent: #2d5b45; --accent-soft: ",
